
.male-panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.tags {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}
.tag {
  padding: 2px 8px;
  border-radius: 10px;
  font-size: 10px;
  background: var(--c-track);
  color: var(--c-primary-deep);
}
.path-label,
.lock-row {
  font-size: 12px;
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--c-border);
}
.path-label i,
.lock-row i {
  color: var(--c-primary-deep);
  width: 12px;
}
.mini-timeline {
  border-top: 1px dashed var(--c-track);
  padding-top: 8px;
}
.mt-title {
  font-size: 10px;
  color: var(--c-text-muted);
  margin-bottom: 4px;
}
.mt-nodes {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}
.mt-node {
  font-size: 9px;
  padding: 2px 6px;
  border-radius: 8px;
  background: var(--c-track);
  color: var(--c-text-muted);
}
.mt-node.passed {
  background: var(--c-accent);
  color: #fff;
}
