
.social-status {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
}
.icon {
  width: 14px;
  color: var(--c-primary-deep);
  flex-shrink: 0;
}
.icon.warn {
  color: var(--c-danger-start);
}
.label {
  color: var(--c-text-muted);
  flex-shrink: 0;
  width: 68px;
}
.bar {
  flex: 1;
  height: 6px;
  border-radius: 3px;
  background: var(--c-track);
  overflow: hidden;
}
.fill {
  height: 100%;
  background: var(--c-primary);
  transition: width 0.5s ease, background 0.5s ease;
}
.fill.accent {
  background: var(--c-accent);
}
.fill.warn {
  background: linear-gradient(90deg, var(--c-danger-start), var(--c-danger-end));
}
.num {
  width: 24px;
  text-align: right;
  color: var(--c-border);
  font-weight: 600;
  flex-shrink: 0;
}
.tag {
  padding: 2px 8px;
  border-radius: 10px;
  font-size: 10px;
}
.tag-idle {
  background: var(--c-track);
  color: var(--c-text-muted);
}
.tag-mid {
  background: #ecd9c4;
  color: var(--c-primary-deep);
}
.tag-deep {
  background: var(--c-accent);
  color: #fff;
}
