
.ring-wrap {
  position: relative;
  width: 76px;
  height: 76px;
  flex-shrink: 0;
}
.petals {
  position: absolute;
  inset: 0;
}
.petal {
  position: absolute;
  top: 50%;
  left: 50%;
  font-size: 15px;
  line-height: 1;
  color: var(--c-track);
  transition: color 0.6s ease;
}
.petal.active {
  color: var(--c-accent);
}
.core {
  position: absolute;
  inset: 9px;
  border-radius: 50%;
  background: var(--c-surface);
  border: 2px solid var(--c-primary);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  transition: border-color 0.6s ease, background 0.6s ease;
}
.core.deep {
  border-color: var(--c-accent-deep);
  background: linear-gradient(180deg, var(--c-surface), #f1e4e6);
}
.value {
  font-weight: 700;
  font-size: 15px;
  color: var(--c-border);
}
.label {
  font-size: 9px;
  color: var(--c-text-muted);
  margin-top: 1px;
  text-align: center;
  padding: 0 4px;
}
