
.npc-drawer {
  border-top: 1px dashed var(--c-track);
  padding-top: 8px;
}
summary {
  cursor: pointer;
  list-style: none;
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 600;
  color: var(--c-primary-deep);
  user-select: none;
}
summary::-webkit-details-marker {
  display: none;
}
.caret {
  font-size: 9px;
  transition: transform 0.2s ease;
}
.npc-drawer[open] .caret {
  transform: rotate(90deg);
}
.count {
  font-size: 10px;
  color: var(--c-text-muted);
  background: var(--c-track);
  border-radius: 8px;
  padding: 0 6px;
}
.npc-list {
  margin-top: 6px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.empty {
  font-size: 11px;
  color: var(--c-text-muted);
}
.npc-row {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 6px 8px;
  background: var(--c-background);
  border: 1px dashed var(--c-track);
  border-radius: 6px;
}
.npc-head {
  display: flex;
  align-items: baseline;
  gap: 6px;
}
.npc-name {
  font-weight: 700;
  font-size: 12px;
  color: var(--c-border);
}
.npc-id {
  font-size: 10px;
  color: var(--c-text-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.npc-meta {
  display: flex;
  align-items: center;
  gap: 6px;
}
.tag {
  font-size: 10px;
  color: var(--c-primary-deep);
  background: var(--c-track);
  border-radius: 8px;
  padding: 1px 6px;
  flex-shrink: 0;
}
.bar {
  flex: 1;
  height: 5px;
  border-radius: 3px;
  background: var(--c-track);
  overflow: hidden;
}
.fill {
  height: 100%;
  background: var(--c-primary);
  transition: width 0.5s ease;
}
.num {
  width: 20px;
  text-align: right;
  font-size: 10px;
  color: var(--c-text-muted);
  flex-shrink: 0;
}
